examples.template:
NavigationStack {
    MonarchThreadPanel(
        replies,
        isFollowing: isFollowing,
        now: {{now|date}},
        onClose: {},
        onFollowingChange: { isFollowing = $0 },
        onRepliesSeen: { _ in },
        root: {
            MonarchMessageRow(MonarchMessageRowAuthor({{root.name}}), time: {{root.time|date}}, now: {{now|date}}) {
                Text({{root.body}})
            }
        },
        composer: {
            MonarchMessageComposer("Reply", text: $draft, placeholder: {{placeholder}}, showsEmojiButton: false, showsFormatting: false) { message in
                replies.append(Reply(id: UUID().uuidString, time: {{now|date}}, authorID: "You", text: message.text))
            }
        },
        reply: { reply, context in
            MonarchMessageRow(
                MonarchMessageRowAuthor(reply.authorID ?? ""),
                time: reply.time,
                now: {{now|date}},
                isGrouped: context.isGrouped
            ) {
                Text(reply.text)
            }
        }
    )
}
.frame(height: 640)

examples.setupTemplate:
struct Reply: MonarchVirtualMessageListItem {
    let id: String
    let time: Date
    let authorID: String?
    let text: String
}
@State private var replies = [
    Reply(id: "r1", time: {{replies.0.time|date}}, authorID: {{replies.0.name}}, text: {{replies.0.body}}),
    Reply(id: "r2", time: {{replies.1.time|date}}, authorID: {{replies.1.name}}, text: {{replies.1.body}}),
    Reply(id: "r3", time: {{replies.2.time|date}}, authorID: {{replies.2.name}}, text: {{replies.2.body}}),
]
@State private var isFollowing = true
@State private var draft = ""

